  (10, 2, 'rejected', 'The project requires students to test against real customers'' financial data, which we can''t support in a course. You''re welcome to resubmit a version that uses synthetic data only.', '2026-08-29 11:20:00-04'),
  (9, 3, 'revision_requested', 'The original scope (multi-site, 200 carts, live hardware integration) is too large for one semester. Please narrow it to one layout and a simulated fleet.', '2026-09-02 13:45:00-04'),
