INSERT INTO public.ticket (id, project, title, description, status, priority, assignee, milestone, created_by, created_at, updated_at) VALUES
  (1, 1, 'Interview dispatchers about booking rules', 'Capture door types, slot lengths and carrier priority rules from the two shift leads.', 'Done', 'High', 24, 1, 2, '2026-10-06 10:00:00-04', '2026-10-12 10:00:00-04'),
  (2, 1, 'Set up repo, CI and staging deploy', 'Monorepo with lint and test checks on every pull request; auto-deploy main to staging.', 'Done', 'Medium', 26, 1, 35, '2026-10-07 11:00:00-04', '2026-10-13 13:00:00-04'),
  (3, 1, 'Carrier booking form', 'Carriers pick a date, load type and estimated pallets; system offers open slots.', 'Done', 'High', 35, 2, 21, '2026-10-20 12:00:00-04', '2026-10-26 16:00:00-04'),
  (4, 1, 'Dispatcher daily calendar', 'Doors as columns, 30-minute rows; drag an appointment to move it.', 'Review', 'Urgent', 21, 2, 24, '2026-10-18 13:00:00-04', '2026-10-27 19:00:00-04'),
  (5, 1, 'Double-booking detection', 'Block overlapping appointments on the same door and warn on tight turnarounds.', 'Review', 'High', 24, 3, 26, '2026-10-31 14:00:00-04', '2026-11-09 22:00:00-05'),
  (6, 1, 'Import historical bookings CSV', 'Load the three-month sample so the dashboard has realistic data.', 'To Do', 'Medium', 26, 3, 35, '2026-11-01 15:00:00-05', '2026-11-02 01:00:00-05'),
  (7, 1, 'Utilization and wait-time dashboard', 'Daily door utilization percentage and average yard wait.', 'In Progress', 'Medium', 35, 3, 21, '2026-10-30 16:00:00-04', '2026-11-04 04:00:00-05'),
  (8, 1, 'Write deployment guide for Cobalt IT', 'Step-by-step install, configuration and backup instructions.', 'To Do', 'Low', 21, 4, 24, '2026-11-12 17:00:00-05', '2026-11-13 07:00:00-05'),
  (9, 2, 'Define reminder message templates', 'Short SMS and email templates in English, Spanish and Haitian Creole, reviewed by clinic staff.', 'Done', 'High', 27, 5, 2, '2026-10-06 10:00:00-04', '2026-10-12 10:00:00-04'),
  (10, 2, 'Synthetic patient data generator', 'Generate realistic appointment lists with no real patient information.', 'Done', 'Medium', 22, 5, 14, '2026-10-07 11:00:00-04', '2026-10-13 13:00:00-04'),
  (11, 2, 'Scheduler for 48h and 24h reminders', 'Background job that queues reminders and never sends twice.', 'Done', 'Urgent', 14, 6, 36, '2026-10-20 12:00:00-04', '2026-10-26 16:00:00-04'),
  (12, 2, 'Handle CONFIRM / CANCEL replies', 'Parse one-word replies in all three languages and update the appointment.', 'Review', 'High', 36, 6, 27, '2026-10-18 13:00:00-04', '2026-10-27 19:00:00-04'),
  (13, 2, 'Front-desk status board', 'Live list of today''s patients with confirmed, cancelled and no-reply badges.', 'Review', 'High', 27, 7, 22, '2026-10-31 14:00:00-04', '2026-11-09 22:00:00-05'),
  (14, 2, 'Opt-out and quiet hours', 'Respect STOP replies and never send between 9pm and 8am.', 'To Do', 'High', 22, 7, 14, '2026-11-01 15:00:00-05', '2026-11-02 01:00:00-05'),
  (15, 2, 'Weekly no-show report', 'Compare no-show rate before and after reminders.', 'In Progress', 'Medium', 14, 7, 36, '2026-10-30 16:00:00-04', '2026-11-04 04:00:00-05'),
  (16, 2, 'Accessibility review of staff screens', 'Check contrast, keyboard navigation and screen-reader labels.', 'To Do', 'Low', 36, 8, 27, '2026-11-12 17:00:00-05', '2026-11-13 07:00:00-05'),
  (17, 4, 'Explore inverter dataset', 'Profile the two years of readings: gaps, outliers and timezone issues.', 'Done', 'High', 28, 9, 2, '2026-10-06 10:00:00-04', '2026-10-12 10:00:00-04'),
  (18, 4, 'Weather forecast ingestion', 'Daily job that pulls next-day cloud cover and irradiance forecasts.', 'Done', 'Medium', 18, 9, 17, '2026-10-07 11:00:00-04', '2026-10-13 13:00:00-04'),
  (19, 4, 'Baseline forecast model', 'Clear-sky model scaled by forecast cloud cover; record its error as the baseline.', 'Done', 'High', 17, 10, 15, '2026-10-20 12:00:00-04', '2026-10-26 16:00:00-04'),
  (20, 4, 'Gradient-boosted forecast model', 'Per-system model with weather and seasonal features; must beat the baseline.', 'Review', 'Urgent', 15, 10, 28, '2026-10-18 13:00:00-04', '2026-10-27 19:00:00-04'),
  (21, 4, 'Model accuracy report', 'Mean absolute error by system size and season, with charts.', 'Review', 'Medium', 28, 11, 18, '2026-10-31 14:00:00-04', '2026-11-09 22:00:00-05'),
  (22, 4, 'Member portal forecast page', 'Tomorrow''s hourly forecast next to today''s actual production.', 'To Do', 'High', 18, 11, 17, '2026-11-01 15:00:00-05', '2026-11-02 01:00:00-05'),
  (23, 4, 'Nightly retraining job', 'Retrain weekly and alert if accuracy drops below the baseline.', 'In Progress', 'Low', 17, 11, 15, '2026-10-30 16:00:00-04', '2026-11-04 04:00:00-05'),
  (24, 4, 'Handoff notebook for Greenline analysts', 'Documented notebook that reproduces training and evaluation.', 'To Do', 'Low', NULL, 12, 28, '2026-11-12 17:00:00-05', '2026-11-13 07:00:00-05'),
  (25, 5, 'Document raw file formats for all six buoys', 'Two buoys use an older firmware with different column order.', 'Done', 'High', 16, 13, 2, '2026-10-06 10:00:00-04', '2026-10-12 10:00:00-04'),
  (26, 5, 'Database schema for time series', 'Tables for readings, sensors and quality flags; agree with lab staff.', 'Done', 'Medium', 31, 13, 37, '2026-10-07 11:00:00-04', '2026-10-13 13:00:00-04'),
  (27, 5, 'Ingestion service', 'Watch the upload folder, parse new files and load them idempotently.', 'Done', 'Urgent', 37, 14, 29, '2026-10-20 12:00:00-04', '2026-10-26 16:00:00-04'),
  (28, 5, 'Sensor fault and outlier flags', 'Flag stuck values, sudden spikes and out-of-range readings.', 'Review', 'High', 29, 14, 16, '2026-10-18 13:00:00-04', '2026-10-27 19:00:00-04'),
  (29, 5, 'Public dashboard charts', 'Last 7 days per buoy and variable, with flagged points shown in grey.', 'Review', 'High', 16, 15, 31, '2026-10-31 14:00:00-04', '2026-11-09 22:00:00-05'),
  (30, 5, 'CSV download API', 'Researchers choose buoy, variables and date range.', 'To Do', 'Medium', 31, 15, 37, '2026-11-01 15:00:00-05', '2026-11-02 01:00:00-05'),
  (31, 5, 'Alert lab when a buoy goes silent', 'Email the lab if no data arrives for two hours.', 'In Progress', 'Medium', 37, 15, 29, '2026-10-30 16:00:00-04', '2026-11-04 04:00:00-05'),
  (32, 5, 'Operations runbook', 'How to add a buoy, re-run ingestion and restore from backup.', 'To Do', 'Low', 29, 16, 16, '2026-11-12 17:00:00-05', '2026-11-13 07:00:00-05'),
  (33, 7, 'Map current matching process', 'Shadow the program coordinator and document every step and email.', 'Done', 'High', 19, 17, 2, '2026-10-06 10:00:00-04', '2026-10-12 10:00:00-04'),
  (34, 7, 'Tutor and family profile models', 'Subjects, grade levels, availability windows and language preferences.', 'Done', 'Medium', 30, 17, 33, '2026-10-07 11:00:00-04', '2026-10-13 13:00:00-04'),
  (35, 7, 'Tutor sign-up and availability editor', 'Weekly availability grid that works on phones.', 'Done', 'High', 33, 18, 34, '2026-10-20 12:00:00-04', '2026-10-26 16:00:00-04'),
  (36, 7, 'Family help request form', 'Short form in plain language; Spanish version as a stretch goal.', 'Review', 'High', 34, 18, 19, '2026-10-18 13:00:00-04', '2026-10-27 19:00:00-04'),
  (37, 7, 'Match suggestion algorithm', 'Score tutors by subject, availability overlap and distance; staff approve.', 'Review', 'Urgent', 19, 19, 30, '2026-10-31 14:00:00-04', '2026-11-09 22:00:00-05'),
  (38, 7, 'Session logging', 'Tutors log date, duration and topics after each session.', 'To Do', 'Medium', 30, 19, 33, '2026-11-01 15:00:00-05', '2026-11-02 01:00:00-05'),
  (39, 7, 'Funder hours report', 'Hours by tutor, subject and neighborhood for a date range.', 'In Progress', 'Medium', 33, 19, 34, '2026-10-30 16:00:00-04', '2026-11-04 04:00:00-05'),
  (40, 7, 'Spanish translation of family pages', 'Translate and have Brightpath staff review the wording.', 'To Do', 'Low', 34, 20, 19, '2026-11-12 17:00:00-05', '2026-11-13 07:00:00-05'),
  (41, 8, 'Gather room list and booking policies', 'Room capacities, equipment, max booking length and branch hours.', 'Done', 'High', 25, 21, 2, '2026-10-06 10:00:00-04', '2026-10-12 10:00:00-04'),
  (42, 8, 'Mock library card lookup API', 'Stub that validates card numbers and returns the patron''s home branch.', 'Done', 'Medium', 23, 21, 20, '2026-10-07 11:00:00-04', '2026-10-13 13:00:00-04'),
  (43, 8, 'Room search and booking flow', 'Pick branch, date and time; see available rooms and book in two taps.', 'Done', 'Urgent', 20, 22, 32, '2026-10-20 12:00:00-04', '2026-10-26 16:00:00-04'),
  (44, 8, 'QR code check-in', 'Printable QR code per room; scanning confirms the booking.', 'Review', 'High', 32, 22, 25, '2026-10-18 13:00:00-04', '2026-10-27 19:00:00-04'),
  (45, 8, 'Automatic no-show release', 'Free the room if nobody checks in within 15 minutes.', 'Review', 'High', 25, 23, 23, '2026-10-31 14:00:00-04', '2026-11-09 22:00:00-05'),
  (46, 8, 'Staff usage reports', 'Bookings and no-shows by branch, room and hour of day.', 'To Do', 'Medium', 23, 23, 20, '2026-11-01 15:00:00-05', '2026-11-02 01:00:00-05'),
  (47, 8, 'Load test peak booking times', 'Simulate the 9am rush on exam weeks.', 'In Progress', 'Low', 20, 23, 32, '2026-10-30 16:00:00-04', '2026-11-04 04:00:00-05'),
  (48, 8, 'Printable QR signs for every room', 'Generate a PDF of door signs with room name and code.', 'To Do', 'Low', NULL, 24, 25, '2026-11-12 17:00:00-05', '2026-11-13 07:00:00-05');
