INSERT INTO public.chat_message (id, channel, sender, body, created_at, deleted_at, deleted_by) VALUES
  (1, 1, 24, 'Morning all. Dispatcher calendar is in Review, Henry can someone pair with you on the drag-and-drop edge cases today?', '2026-11-12 09:14:00-05', NULL, NULL),
  (2, 1, 21, 'Yes please. Dragging an appointment onto a door that''s already booked still lets it drop for a split second before snapping back.', '2026-11-12 09:31:00-05', NULL, NULL),
  (3, 1, 35, 'I can pair after 2pm. I need the same overlap check for the utilization dashboard anyway.', '2026-11-12 09:40:00-05', NULL, NULL),
  (4, 1, 26, 'Pushed the wrong branch, ignore the last PR link', '2026-11-12 10:05:00-05', '2026-11-12 10:06:00-05', 26),
  (5, 1, 26, 'Heads up: the historical bookings CSV from Cobalt uses DD/MM dates. I''ll normalize them on import.', '2026-11-12 10:07:00-05', NULL, NULL),
  (6, 1, 2, 'Nice progress on the calendar. For the Sprint 3 demo, please show the double-booking warning live with Priya on the call.', '2026-11-13 16:20:00-05', NULL, NULL),
  (7, 1, 24, 'Will do. Double-booking detection is in Review now, so it should be merged by Monday.', '2026-11-13 16:42:00-05', NULL, NULL),
  (8, 2, 27, 'Front-desk status board is up on staging. Badges for confirmed / cancelled / no reply are working with the synthetic data.', '2026-11-11 11:02:00-05', NULL, NULL),
  (9, 2, 14, 'Looks great. The no-show report needs the reply timestamps, can you expose them in the API?', '2026-11-11 11:20:00-05', NULL, NULL),
  (10, 2, 27, 'Sure, adding replied_at to the appointment endpoint this afternoon.', '2026-11-11 11:26:00-05', NULL, NULL),
  (11, 2, 22, 'Quiet hours question: if a reminder is due at 9:30pm, do we send it at 8am the next day or skip it?', '2026-11-12 14:48:00-05', NULL, NULL),
  (12, 2, 2, 'Check with Marcus, but 8am the next day is usually what clinics want. Write the decision down in the ticket.', '2026-11-12 17:05:00-05', NULL, NULL),
  (13, 2, 36, 'Started the accessibility pass. Contrast on the cancelled badge fails WCAG AA, I''ll darken it.', '2026-11-13 10:12:00-05', NULL, NULL),
  (14, 3, 15, 'Gradient-boosted model beats the baseline by 23% MAE on the validation months. Notebook is linked in the ticket.', '2026-11-10 13:30:00-05', NULL, NULL),
  (15, 3, 28, 'Nice! Can you split the error by system size for the accuracy report?', '2026-11-10 13:52:00-05', NULL, NULL),
  (16, 3, 15, 'Already on it. Small systems are noisier, probably because of shading.', '2026-11-10 14:05:00-05', NULL, NULL),
  (17, 3, 18, 'Member portal forecast page is blocked until the model API is deployed. Who owns that?', '2026-11-12 09:18:00-05', NULL, NULL),
  (18, 3, 17, 'I''ll deploy it with the retraining job. Aiming for Friday.', '2026-11-12 09:33:00-05', NULL, NULL),
  (19, 3, 2, 'Remember Sofia asked for the handoff notebook to run end to end on a fresh machine. Please test that before the final demo.', '2026-11-14 11:45:00-05', NULL, NULL),
  (20, 4, 31, 'Buoy B4 sent a stuck salinity value all night (31.20 for 9 hours). Fault flag caught it, so the pipeline works!', '2026-11-11 08:47:00-05', NULL, NULL),
  (21, 4, 29, 'Great, that''s exactly the case Daniel wanted. I''ll add a screenshot to the Review ticket.', '2026-11-11 09:02:00-05', NULL, NULL),
  (22, 4, 16, 'Dashboard now greys out flagged points. B4 looks right on staging.', '2026-11-11 09:15:00-05', NULL, NULL),
  (23, 4, 37, 'Silent-buoy alert sends a test email to the .test inbox. Two hours felt long during testing, should it be configurable?', '2026-11-12 16:30:00-05', NULL, NULL),
  (24, 4, 2, 'Configurable is good, but keep two hours as the default since that''s what the lab asked for.', '2026-11-13 10:10:00-05', NULL, NULL),
  (25, 4, 31, 'Starting the CSV download API. Planning ISO timestamps in UTC to match the data dictionary.', '2026-11-14 15:22:00-05', NULL, NULL),
  (26, 5, 33, 'Funder hours report draft is ready: hours by tutor, subject and neighborhood. Feedback welcome.', '2026-11-10 17:40:00-05', NULL, NULL),
  (27, 5, 19, 'Match suggestion algorithm is in Review. It now weights availability overlap twice as much as distance.', '2026-11-10 18:05:00-05', NULL, NULL),
  (28, 5, 30, 'Session logging form is next. Should tutors log topics as free text or pick from a list?', '2026-11-11 12:15:00-05', NULL, NULL),
  (29, 5, 34, 'Hannah mentioned free text plus subject tags, so we can still group them in the report.', '2026-11-11 12:30:00-05', NULL, NULL),
  (30, 5, 2, 'Good call to check with the sponsor. Please keep the family request form in plain language; that came up in the last review.', '2026-11-12 15:00:00-05', NULL, NULL),
  (31, 5, 34, 'Got it. I''ll start the Spanish translation once the English wording is final.', '2026-11-13 09:45:00-05', NULL, NULL),
  (32, 6, 32, 'QR check-in works on Android and iOS. The scanner page needs camera permission, I added a short explanation screen.', '2026-11-11 10:20:00-05', NULL, NULL),
  (33, 6, 25, 'Automatic no-show release is in Review. Rooms free up exactly 15 minutes after the start if nobody checks in.', '2026-11-11 10:41:00-05', NULL, NULL),
  (34, 6, 20, 'Load test results: the booking flow handles 200 simultaneous requests before slowing down. Writing it up now.', '2026-11-12 13:05:00-05', NULL, NULL),
  (35, 6, 23, 'Starting the staff usage reports. Tom wants bookings and no-shows by branch and hour of day.', '2026-11-12 13:30:00-05', NULL, NULL),
  (36, 6, 2, 'Strong sprint. For the final demo, show a full booking, a check-in and a no-show release in one flow.', '2026-11-14 09:15:00-05', NULL, NULL);
